'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),out=path.join(root,'outputs/youth-20years-20261011');
const seeds=['youth20-a','youth20-b','youth20-c'],audits=seeds.map(s=>JSON.parse(fs.readFileSync(path.join(out,s+'-audit.json'),'utf8')));
const controls=JSON.parse(fs.readFileSync(path.join(out,'controls.json'),'utf8'));
const G=require(path.join(out,'source/dist/player-generation.js'));
const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null,sum=a=>a.reduce((s,x)=>s+x,0),median=a=>{const b=[...a].sort((a,b)=>a-b);return b.length?b[Math.floor(b.length/2)]:null;};
const labels={ENG:'England',ESP:'Spanien',GER:'Deutschland',ITA:'Italien',FRA:'Frankreich',POR:'Portugal',NED:'Niederlande',BEL:'Belgien',AUT:'Österreich',SUI:'Schweiz',TUR:'Türkei',GRE:'Griechenland'};
const latest=Math.min(...audits.map(a=>a.seasonStats.at(-1)?.season||0));
function countrySeries(country,simulationOnly=false){
 return Array.from({length:latest+1},(_,season)=>{
  const samples=audits.map(a=>{const rows=a.snapshots.filter(r=>r.country===country&&r.simulationOnly===simulationOnly&&!r.managed&&(season===0?r.phase==='initial':r.season===season&&r.phase==='closed')),base=a.snapshots.filter(r=>r.country===country&&r.simulationOnly===simulationOnly&&!r.managed&&r.phase==='initial');
   assert(rows.length===base.length&&rows.length>0);const total=sum(rows.map(r=>r.rosterSize));return{rosterChangePct:100*(mean(rows.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),startingChangePct:100*(mean(rows.map(r=>r.startingQuality))/mean(base.map(r=>r.startingQuality))-1),meanAge:mean(rows.map(r=>r.meanAge)),youthSharePct:100*sum(rows.map(r=>r.origins.youth))/total,freeSharePct:100*sum(rows.map(r=>r.origins.free+r.origins.unknown))/total,startSharePct:100*sum(rows.map(r=>r.origins.start))/total,budget:mean(rows.map(r=>r.budget)),balance:mean(rows.map(r=>r.balance)),qualityBands:Object.fromEntries(['very-weak','weak','normal','good','very-good'].map(b=>[b,100*sum(rows.map(r=>r.qualityBands[b]))/total]))};});
  const field=k=>mean(samples.map(s=>s[k]));return{season,rosterChangePct:field('rosterChangePct'),rosterRangePct:[Math.min(...samples.map(s=>s.rosterChangePct)),Math.max(...samples.map(s=>s.rosterChangePct))],startingChangePct:field('startingChangePct'),startingRangePct:[Math.min(...samples.map(s=>s.startingChangePct)),Math.max(...samples.map(s=>s.startingChangePct))],meanAge:field('meanAge'),youthSharePct:field('youthSharePct'),freeSharePct:field('freeSharePct'),startSharePct:field('startSharePct'),budget:field('budget'),balance:field('balance'),qualityBands:Object.fromEntries(['very-weak','weak','normal','good','very-good'].map(b=>[b,mean(samples.map(s=>s.qualityBands[b]))]))};
 });
}
function totalSeries(){return Array.from({length:latest+1},(_,season)=>{const samples=audits.map(a=>{const row=phase=>a.snapshots.filter(r=>!r.simulationOnly&&!r.managed&&(phase==='initial'?r.phase===phase:r.phase==='closed'&&r.season===season)),rows=row('closed'),base=row('initial');if(season===0)return{roster:0,starting:0};return{roster:100*(mean(rows.map(r=>r.quality))/mean(base.map(r=>r.quality))-1),starting:100*(mean(rows.map(r=>r.startingQuality))/mean(base.map(r=>r.startingQuality))-1)};});return{season,rosterChangePct:mean(samples.map(s=>s.roster)),startingChangePct:mean(samples.map(s=>s.starting)),rosterRangePct:[Math.min(...samples.map(s=>s.roster)),Math.max(...samples.map(s=>s.roster))]};});}
const baseline=Object.values(controls.groups).map(g=>({country:g.country,label:labels[g.country],tier:g.tier,startCount:g.start.length,youthCount:g.youth.length,juvenileGapPct:100*(mean(g.youth)/mean(g.start)-1),primeGapPct:100*(mean(g.youth)/mean(g.startPrime)-1),meanInitialBudget:mean(g.budget),youthProfiles:Object.fromEntries(Object.entries(g.profiles).map(([k,v])=>[k,v.n]))}));
const line=b=>b.line||Object.keys(G.POSITION_WEIGHTS).find(p=>Math.abs(G.positionQuality(b.skills,p)-b.quality)<1e-10);
const matureRows=audits.flatMap(a=>a.births.filter(b=>b.kind==='youth'&&b.clubId!=='AUT-5'&&b.firstSeason<=10&&b.at24).map(b=>({...b,line:line(b),seed:a.seed})));
const primeReferences={};for(const a of audits)for(const b of a.births.filter(b=>b.kind==='start'&&b.clubId!=='AUT-5'&&b.age>=24&&b.age<=29)){for(const k of [a.seed+':'+b.country+':'+line(b),'all:'+b.country+':'+line(b)])(primeReferences[k]??=[]).push(b.quality);}
const matured=Object.keys(labels).map(country=>{const rows=matureRows.filter(b=>b.country===country),all=audits.flatMap(a=>a.births.filter(b=>b.kind==='youth'&&b.clubId!=='AUT-5'&&b.country===country&&b.firstSeason<=10)),reference=rows.map(b=>mean(primeReferences[b.seed+':'+country+':'+b.line]||primeReferences['all:'+country+':'+b.line]||[]));assert(reference.every(Number.isFinite));return{country,n:rows.length,eligibleBorn:all.length,observedTo24Pct:100*rows.length/all.length,selectedBirthGapPct:100*(mean(rows.map(b=>b.quality))/mean(all.map(b=>b.quality))-1),medianGrowthPct:median(rows.map(b=>100*(b.at24.quality/b.quality-1))),meanGrowthPct:rows.length?100*(mean(rows.map(b=>b.at24.quality))/mean(rows.map(b=>b.quality))-1):null,relativePrimeStartPct:rows.length?100*(mean(rows.map(b=>b.at24.quality))/mean(reference)-1):null,medianMinutes:median(rows.map(b=>b.at24.minutes)),noPositiveGrowthPct:rows.length?100*rows.filter(b=>b.at24.positive===0).length/rows.length:null};});
const maturedByPosition=Object.keys(G.POSITION_WEIGHTS).map(position=>{const rows=matureRows.filter(b=>b.line===position);return{position,n:rows.length,meanGrowthPct:rows.length?100*(mean(rows.map(b=>b.at24.quality))/mean(rows.map(b=>b.quality))-1):null,medianGrowthPct:median(rows.map(b=>100*(b.at24.quality/b.quality-1))),medianMinutes:median(rows.map(b=>b.at24.minutes)),noPositiveGrowthPct:rows.length?100*rows.filter(b=>b.at24.positive===0).length/rows.length:null};});
const countries=Object.keys(labels).map(country=>({country,label:labels[country],tier:controls.groups[country].tier,series:countrySeries(country),cupSeries:countrySeries(country,true)}));
const tierSeries=Array.from({length:latest+1},(_,season)=>{const values=audits.map(a=>{const rows=a.snapshots.filter(r=>!r.simulationOnly&&!r.managed&&(season===0?r.phase==='initial':r.phase==='closed'&&r.season===season));return 100*(mean(rows.filter(r=>r.tier==='A').map(r=>r.quality))/mean(rows.filter(r=>r.tier==='D').map(r=>r.quality))-1);});return{season,aRelativeToDPct:mean(values),range:[Math.min(...values),Math.max(...values)]};});
let finalAge=null;if(latest===20){finalAge=[];for(const seed of seeds){const c=JSON.parse(fs.readFileSync(path.join(out,seed+'-checkpoint.json'),'utf8'));for(const country of Object.keys(labels)){const p=c.world.clubs.filter(b=>b.leagueId&&b.id!==c.manager.managedClubId&&b.countryId===country).flatMap(b=>b.roster);finalAge.push({seed,country,players:p.length,over40:p.filter(p=>p.age>=40).length,maximumAge:Math.max(...p.map(p=>p.age))});}}}
const summary={generatedAt:new Date().toISOString(),complete:latest===20,seeds,completedSeasons:audits.map(a=>({seed:a.seed,seasons:a.seasonStats.length})),latestCommonSeason:latest,fixtures:sum(audits.map(a=>sum(a.seasonStats.map(s=>s.fixtures)))),method:'Native compact simulation, actual minutes/ratings/development/aging/market; mean primary-position quality per club, same clubs at baseline; managed AUT-5 excluded; fixed formation selected by native AI; relative figures only.',controls:{countryPairs:controls.countryPairs,countryMatches:controls.countryMatches,budgetPairs:controls.budgetPairs,budgetMatches:controls.budgetMatches,baselineSeeds:controls.baselineSeeds,idealPlayers:controls.ideal.length,idealMeanGrowthPct:100*(mean(controls.ideal.map(p=>p.at24))/mean(controls.ideal.map(p=>p.initial))-1)},totalSeries:totalSeries(),tierSeries,countries,baseline,matured,finalAge,learning:audits.map(a=>({seed:a.seed,...a.changes})),minutes:audits.map(a=>({seed:a.seed,seasons:a.seasonStats.map(s=>({season:s.season,youthSharePct:100*s.minutes.youth/s.allMinutes,ratings:s.ratings}))}))};
summary.cohortSummary={n:matureRows.length,eligibleBorn:sum(matured.map(r=>r.eligibleBorn)),selectedBirthGapPct:100*(mean(matureRows.map(b=>b.quality))/mean(audits.flatMap(a=>a.births.filter(b=>b.kind==='youth'&&b.clubId!=='AUT-5'&&b.firstSeason<=10)).map(b=>b.quality))-1)};summary.maturedByPosition=maturedByPosition;fs.writeFileSync(path.join(out,'summary.json'),JSON.stringify(summary,null,2));
console.log(JSON.stringify(process.argv.includes('--quiet')?{complete:summary.complete,latest,fixtures:summary.fixtures,total:summary.totalSeries.at(-1),tierGap:summary.tierSeries.at(-1)}:{complete:summary.complete,latest,fixtures:summary.fixtures,total:summary.totalSeries.at(-1),countries:countries.map(c=>({country:c.country,...c.series.at(-1)})),matured},null,2));
